// spec: specs/client-ordering.md §8 · кейсы co-24…co-28 (.qa/tests/client-ordering/) — קטגוריית «מוצרים אחרונים»
// #8103a9 (9f381ae90c6d4f6b828103a9, commit 1d63a05; прошёл ручную QA 18.10, «הושלם»).
// Первые 4 теста только смотрят (@prod-safe): место и стиль чипа, шторка, состав/порядок против истории заказов, фильтры внутри.
// Тесты @data меняют корзину buyer и создают заказы/товары «QA-AUTO-client-ordering-8103-…»:
//   корзина снимается до теста и восстанавливается после (_cart-snapshot.ts); заказы отклоняются, товары удаляются (afterAll).
// ⚠️ @data-тесты НЕ запускать параллельно с другими тестами корзины buyer (cart-checkout, cart-remove-no-flash, reorder,
//    orders/order-lifecycle, inventory/inventory-lifecycle, picking/picking-flow, customers-pricing/pricing-lifecycle …) — общая корзина.
// Не автоматизировано: клиент без заказов не видит чип, раздельная история клиентов — нет второго клиента (co-28, test.skip).
import { test, expect, Page } from '@playwright/test';
import { auth, createStockedProduct, deleteProduct, placeOrder, cleanup } from '../orders/_qa-order';
import { cartSnapshot, restoreCartIn, CartLine } from './_cart-snapshot';

test.use({ storageState: auth('buyer') });

const RECENT = 'מוצרים אחרונים';
const counter = (page: Page) => page.getByText(/^(\d+ מוצרים|מוצר אחד)$/).first();
const countOf = async (page: Page) => {
  const t = await counter(page).innerText();
  return t === 'מוצר אחד' ? 1 : Number(t.match(/\d+/)![0]);
};
const chip = (page: Page, name: string) => page.getByRole('button', { name, exact: true });
const cardName = (text: string) => text.split('\n').map((s) => s.trim()).filter((s) => s && s !== 'אזל' && !s.startsWith('₪'))[0];

async function openShop(page: Page) {
  await page.goto('/shop');
  await expect(page.getByRole('searchbox', { name: 'חיפוש מוצר' })).toBeVisible({ timeout: 30_000 });
  await expect(page.locator('article').first()).toBeVisible({ timeout: 30_000 });
  await expect(chip(page, RECENT)).toBeVisible({ timeout: 20_000 }); // чип появляется после загрузки истории
}

async function openRecent(page: Page) {
  await openShop(page);
  await chip(page, RECENT).click();
  await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');
  await expect(page.getByText(RECENT, { exact: true }).last()).toBeVisible();
  await expect(counter(page)).toBeVisible({ timeout: 20_000 });
}

/** Все карточки текущей выдачи (с догрузкой прокруткой), названия по порядку. */
async function allCardNames(page: Page) {
  const n = await countOf(page);
  const cards = page.locator('article');
  await expect.poll(async () => {
    await page.mouse.wheel(0, 20000);
    return cards.count();
  }, { timeout: 30_000 }).toBe(n);
  return (await cards.allInnerTexts()).map(cardName);
}

async function openSheet(page: Page) {
  await page.getByRole('button', { name: /^סינון ומיון/ }).click();
  const sheet = page.getByRole('dialog').filter({ hasText: 'סינון ומיון' });
  await expect(sheet).toBeVisible();
  return sheet;
}
async function applySheet(page: Page) {
  const sheet = page.getByRole('dialog').filter({ hasText: 'סינון ומיון' });
  await sheet.getByRole('button', { name: /^הצגת (\d+ מוצרים|מוצר אחד)$/ }).click();
  await expect(sheet).toHaveCount(0);
}

/** История заказов buyer (новые сверху) из ответа списка «ההזמנות שלי». */
async function orderHistory(page: Page) {
  const resp = page.waitForResponse((r) => {
    const u = decodeURIComponent(r.url());
    return u.includes('/rest/v1/orders?select=') && u.includes('products(name') && r.request().method() === 'GET';
  }, { timeout: 30_000 });
  await page.goto('/shop/orders');
  const data = (await (await resp).json()) as { order_no: number; created_at: string; order_items: { products: { name: string } | null }[] }[];
  data.sort((a, b) => b.created_at.localeCompare(a.created_at));
  return data;
}

test.describe('client-ordering — «מוצרים אחרונים» (צפייה)', () => {
  test('«מוצרים אחרונים» — מיד אחרי «הכל», באותו עיצוב; בחירה מסמנת אותו וכותרת «מוצרים אחרונים» #8103a9 @desktop @prod-safe', async ({ page }) => {
    await openShop(page);
    const row = await page.evaluate(() => {
      const bs = [...document.querySelectorAll('button[aria-pressed]')] as HTMLElement[];
      return bs.slice(0, 4).map((b) => {
        const r = b.getBoundingClientRect();
        const cs = getComputedStyle(b);
        return { t: (b.textContent || '').trim(), x: r.x, right: r.right, y: Math.round(r.y), h: Math.round(r.height), bg: cs.backgroundColor, radius: cs.borderRadius, font: cs.fontSize + ' ' + cs.fontWeight, pressed: b.getAttribute('aria-pressed') };
      });
    });
    expect(row.map((c) => c.t).slice(0, 2), 'порядок чипов: «הכל», затем «מוצרים אחרונים»').toEqual(['הכל', RECENT]);
    const [all, recent, next] = row;
    expect(all.pressed).toBe('true');
    expect(recent.pressed).toBe('false');
    // RTL: «מוצרים אחרונים» левее «הכל» и правее следующего чипа, на той же строке
    expect(recent.right).toBeLessThanOrEqual(all.x);
    expect(next.right).toBeLessThanOrEqual(recent.x);
    expect(recent.y).toBe(all.y);
    // тот же вид, что у невыбранного соседа
    expect({ h: recent.h, bg: recent.bg, radius: recent.radius, font: recent.font }).toEqual({ h: next.h, bg: next.bg, radius: next.radius, font: next.font });

    await chip(page, RECENT).click();
    await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');
    await expect(chip(page, 'הכל')).toHaveAttribute('aria-pressed', 'false');
    const bgNow = await chip(page, RECENT).evaluate((b) => getComputedStyle(b).backgroundColor);
    expect(bgNow, 'выбранный «מוצרים אחרונים» залит как выбранный «הכל»').toBe(all.bg);
    await expect(page.getByText(RECENT, { exact: true }).last()).toBeVisible();
    expect(await countOf(page)).toBeGreaterThan(0);
    await expect(page.getByText('כל המוצרים')).toHaveCount(0);
    await expect(page.locator('article').first()).toContainText('₪');
  });

  test('«מוצרים אחרונים» בשכבת «סינון ומיון» אחרי «כל הקטגוריות»; בחירה משם — אותה רשימה #8103a9 @desktop @prod-safe', async ({ page }) => {
    await openRecent(page);
    const n = await countOf(page);
    await chip(page, 'הכל').click();
    await expect(page.getByText('כל המוצרים')).toBeVisible();

    const sheet = await openSheet(page);
    const lines = (await sheet.innerText()).split('\n').map((l) => l.trim()).filter(Boolean);
    expect(lines[lines.indexOf('כל הקטגוריות') + 1], 'в шторке «מוצרים אחרונים» сразу после «כל הקטגוריות»').toBe(RECENT);
    await sheet.getByRole('radio', { name: RECENT, exact: true }).click();
    await expect(sheet.getByRole('radio', { name: RECENT, exact: true })).toBeChecked();
    await applySheet(page);
    await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');
    await expect(page.getByText(RECENT, { exact: true }).last()).toBeVisible();
    await expect.poll(() => countOf(page)).toBe(n);
  });

  test('תוכן: כל מוצר פעם אחת, רק מוצרים מההזמנות, לפי ההזמנה האחרונה (חדש→ישן); מוצר שלא ברשימה — בארכיון #8103a9 @desktop @prod-safe', async ({ page }) => {
    test.setTimeout(180_000);
    const history = await orderHistory(page);
    expect(history.length, 'у buyer есть заказы').toBeGreaterThan(0);
    const lastIdx = new Map<string, number>(); // имя → индекс самого нового заказа с этим товаром
    history.forEach((o, i) => o.order_items.forEach((it) => {
      const name = it.products?.name;
      if (name && !lastIdx.has(name)) lastIdx.set(name, i);
    }));

    await openRecent(page);
    const names = await allCardNames(page);
    expect(names.length).toBeGreaterThan(0);
    expect(new Set(names).size, `без дублей: ${names.join(' | ')}`).toBe(names.length);
    for (const n of names) expect(lastIdx.has(n), `«${n}» есть в истории заказов`).toBe(true);
    const idx = names.map((n) => lastIdx.get(n)!);
    for (let i = 1; i < idx.length; i++) {
      expect(idx[i], `порядок: «${names[i - 1]}» (заказ #${history[idx[i - 1]].order_no}) выше «${names[i]}» (заказ #${history[idx[i]].order_no})`).toBeGreaterThanOrEqual(idx[i - 1]);
    }

    // товар из истории, которого нет в списке, должен быть удалён из каталога (архив): в «הכל» поиском не находится
    const missing = [...lastIdx.keys()].filter((n) => !names.includes(n) && !n.startsWith('QA-AUTO'));
    test.info().annotations.push({ type: '#8103a9', description: `в списке ${names.length}; в истории ${lastIdx.size} товаров; не в списке (не QA-AUTO): ${missing.length}` });
    if (missing.length) {
      await chip(page, 'הכל').click();
      const search = page.getByRole('searchbox', { name: 'חיפוש מוצר' });
      for (const n of missing.slice(0, 20)) {
        await search.fill(n);
        const w = n.split(' ')[0];
        await expect.poll(async () => (await page.getByText('לא נמצאו מוצרים תואמים').count()) > 0
          || (await page.locator('article').allInnerTexts()).every((t) => t.includes(w)), { timeout: 15_000 }).toBe(true);
        await expect(page.locator('article').filter({ hasText: n }), `«${n}» заказан, есть в каталоге, но не в «מוצרים אחרונים»`).toHaveCount(0);
      }
    }
  });

  test('בתוך הקטגוריה עובדים חיפוש, «במלאי בלבד», «מחירון אישי בלבד» ומיון לפי מחיר #8103a9 @desktop @prod-safe', async ({ page }) => {
    await openRecent(page);
    const n = await countOf(page);
    const names = await allCardNames(page);
    test.skip(names.length < 2, 'в «מוצרים אחרונים» меньше 2 товаров');

    // поиск
    const search = page.getByRole('searchbox', { name: 'חיפוש מוצר' });
    const word = names[1].split(' ')[0];
    await search.fill(word);
    await expect.poll(async () => (await page.locator('article').allInnerTexts()).every((t) => t.includes(word)), { timeout: 15_000 }).toBe(true);
    expect(await countOf(page)).toBeLessThanOrEqual(n);
    await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');
    await search.fill('QA-NO-SUCH-XYZ');
    await expect(page.getByText('לא נמצאו מוצרים תואמים')).toBeVisible({ timeout: 15_000 });
    await search.fill('');
    await expect.poll(() => countOf(page), { timeout: 15_000 }).toBe(n);
    await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');

    // «במלאי בלבד»
    let sheet = await openSheet(page);
    await sheet.getByRole('radio', { name: 'במלאי בלבד' }).click();
    await applySheet(page);
    await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');
    await expect(page.getByText(RECENT, { exact: true }).last()).toBeVisible();
    const stock = page.getByText('לא נמצאו מוצרים תואמים').or(counter(page));
    await expect(stock.first()).toBeVisible({ timeout: 15_000 });
    if (await page.locator('article').count()) {
      expect(await countOf(page)).toBeLessThanOrEqual(n);
      for (const t of await page.locator('article').allInnerTexts()) expect(t.split('\n').map((s) => s.trim())).not.toContain('אזל');
    }
    sheet = await openSheet(page);
    await sheet.getByRole('radio', { name: 'הכל', exact: true }).click();
    await applySheet(page);
    await expect.poll(() => countOf(page), { timeout: 15_000 }).toBe(n);

    // «מחירון אישי בלבד»
    sheet = await openSheet(page);
    await sheet.getByRole('radio', { name: 'מחירון אישי בלבד' }).click();
    await applySheet(page);
    await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');
    await expect(page.getByText('לא נמצאו מוצרים תואמים').or(counter(page)).first()).toBeVisible({ timeout: 15_000 });
    if (await page.locator('article').count()) expect(await countOf(page)).toBeLessThanOrEqual(n);
    sheet = await openSheet(page);
    await sheet.getByRole('radio', { name: 'כל המוצרים' }).click();
    await applySheet(page);
    await expect.poll(() => countOf(page), { timeout: 15_000 }).toBe(n);

    // сортировка «מחיר: מהזול ליקר» — тот же набор, цены не убывают
    sheet = await openSheet(page);
    await sheet.getByRole('radio', { name: 'מחיר: מהזול ליקר' }).click();
    await applySheet(page);
    await expect(chip(page, RECENT)).toHaveAttribute('aria-pressed', 'true');
    await expect.poll(() => countOf(page), { timeout: 15_000 }).toBe(n);
    const sorted = await allCardNames(page);
    expect([...sorted].sort()).toEqual([...names].sort());
    const prices = (await page.locator('article').allInnerTexts()).map((t) => Number(t.match(/₪([\d,]+(?:\.\d+)?)/)![1].replace(/,/g, '')));
    for (let i = 1; i < prices.length; i++) expect(prices[i], `цены по возрастанию: ${prices.join(', ')}`).toBeGreaterThanOrEqual(prices[i - 1]);
    // вернуть сортировку по умолчанию (хранится только в окне теста)
    sheet = await openSheet(page);
    await sheet.getByRole('radio', { name: 'מומלץ' }).click();
    await applySheet(page);
  });

  test('לקוח חדש בלי הזמנות לא רואה «מוצרים אחרונים»; אחרי הזמנה ראשונה — מופיע; היסטוריה נפרדת לכל לקוח #8103a9 @desktop @prod-safe', async () => {
    test.skip(true, 'нужен второй клиентский аккаунт без заказов (L-20261003-1) — только вручную, co-28');
  });
});

test.describe('client-ordering — «מוצרים אחרונים»: «+» ועדכון אחרי הזמנה (@data, корзина buyer)', () => {
  test.describe.configure({ mode: 'serial' });
  const TS = Date.now().toString().slice(-7);
  const P = [1, 2].map((n) => ({ name: `QA-AUTO-client-ordering-8103-${TS}-${n}`, sku: `QACO8103${TS}${n}`, id: '' }));
  const orders: string[] = [];
  let snap: CartLine[] | undefined;

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    snap = await cartSnapshot(await ctx.newPage());
    await ctx.close();
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(300_000);
    await restoreCartIn(browser, snap);
    await cleanup(browser, orders, P.map((p) => p.name));
  });

  test('«+» בקטגוריה מוסיף לעגלה כמו בקטלוג הרגיל #8103a9 @desktop @data', async ({ page }) => {
    await page.goto('/shop/cart');
    const removes = page.getByRole('button', { name: /^הסרה מהעגלה — / });
    await expect(removes.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 30_000 });
    const inCart = new Set((await removes.evaluateAll((bs) => bs.map((b) => b.getAttribute('aria-label') || ''))).map((l) => l.replace(/^הסרה מהעגלה — /, '')));
    await openRecent(page);
    const names = await allCardNames(page);
    // товар в наличии (есть «+»), которого ещё нет в корзине
    let target = '';
    for (const n of names) {
      if (inCart.has(n) || !(await page.getByRole('button', { name: `הוספה לעגלה — ${n}` }).count())) continue;
      target = n;
      break;
    }
    test.skip(!target, 'нет товара в наличии вне корзины');
    const added = page.waitForResponse((r) => r.url().includes('cart_set_item'));
    await page.getByRole('button', { name: `הוספה לעגלה — ${target}` }).click();
    await added;
    await page.goto('/shop/cart');
    const row = page.getByRole('button', { name: `הסרה מהעגלה — ${target}` });
    await expect(row).toHaveCount(1, { timeout: 20_000 });
    // убрать добавленное — корзина как до теста
    await row.click();
    await expect(row).toHaveCount(0, { timeout: 15_000 });
    await expect.poll(async () => (await cartSnapshot(page)).length, { timeout: 20_000 }).toBe(inCart.size); // после перезагрузки — на сервере
  });

  test('אחרי כל הזמנה חדשה הרשימה מתעדכנת: חדש למעלה, מוצר שהוזמן שוב עולה למעלה בלי כפילות; מוצר שנמחק (ארכיון) יורד מהרשימה #8103a9 @desktop @data', async ({ page, browser }) => {
    test.setTimeout(420_000);
    const admin = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    const ap = await admin.newPage();
    for (const p of P) p.id = await createStockedProduct(ap, p.name, p.sku, 1, 10);

    const top = async () => {
      await openRecent(page);
      return allCardNames(page);
    };
    // заказ 1: товар 1
    orders.push(await placeOrder(page, [{ id: P[0].id, name: P[0].name, qty: 1 }], `QA-AUTO-client-ordering-8103-${TS}-o1`));
    let list = await top();
    expect(list[0]).toBe(P[0].name);
    // заказ 2: товар 2
    orders.push(await placeOrder(page, [{ id: P[1].id, name: P[1].name, qty: 1 }], `QA-AUTO-client-ordering-8103-${TS}-o2`));
    list = await top();
    expect(list.slice(0, 2)).toEqual([P[1].name, P[0].name]);
    // заказ 3: снова товар 1 → наверх, один раз
    orders.push(await placeOrder(page, [{ id: P[0].id, name: P[0].name, qty: 1 }], `QA-AUTO-client-ordering-8103-${TS}-o3`));
    list = await top();
    expect(list.slice(0, 2)).toEqual([P[0].name, P[1].name]);
    expect(list.filter((n) => n === P[0].name)).toHaveLength(1);

    // товар 1 удалён (есть заказы → архив) → в «מוצרים אחרונים» его нет
    await deleteProduct(ap, P[0].name);
    await admin.close();
    list = await top();
    expect(list).not.toContain(P[0].name);
    expect(list[0]).toBe(P[1].name);
  });
});
